message.content:
{
  "description": "The creature is a single quadrupedal animal shown in right-facing profile standing on a small patch of dirt with sparse grass and tiny yellow and white flowers. Its overall shape, head, legs and tail are those of a large spotted cat, covered in tan fur with dense black spots, while its entire dorsal side from the back of the neck to the rump is covered by a dark, feathered mantle that looks like the back and chest of a penguin. The mantle is dark gray-black with layered feather texture, with bright yellow patches on the sides of the neck and chest and a thin white border where it meets the spotted fur, and it ends posteriorly in a small pointed feathered tip that sits just above the cat-like tail. The animal has one head with a spotted muzzle, black tear-lines, yellow eyes and small rounded ears, four muscular spotted legs ending in clawed paws, and a thick spotted tail with a dark tip hanging down behind the hind legs.",
  "parts": [
    {
      "part": "head",
      "looks_like": "cheetah-like head with tan fur, black spots, black tear stripe from inner eye to mouth, yellow-brown eyes, white muzzle, chin and whisker area, black nose, and white whiskers",
      "where": "at the anterior end of the body on top of the neck, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears with tan outer fur, black spots and pale inner fur",
      "where": "on top of the head, one more forward-facing, one slightly behind"
    },
    {
      "part": "legs",
      "looks_like": "four muscular legs covered in tan fur with solid black spots of varying size, front legs straight and vertical, hind legs angled at the hock",
      "where": "under the torso, two front under the chest, two hind under the hips"
    },
    {
      "part": "feet",
      "looks_like": "four large paws with tan fur, black spots and visible dark curved claws",
      "where": "at the bottom ends of the four legs, resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "one thick furry tail covered in tan fur with black spots and a dark gray-black tip, bushy at the end",
      "where": "at the posterior end of the body behind the hind legs, hanging down; a second small pointed dark feathered tail tip from the dorsal mantle sits directly above it on the rump"
    },
    {
      "part": "feathers",
      "looks_like": "dense layered feathers, dark gray to black on the back, with bright yellow patches on the sides of the neck/chest and white edging, small pointed feathered tip at the rear",
      "where": "covering the entire dorsal surface from the base of the neck to the rump, draped over the back on top of the spotted fur"
    },
    {
      "part": "markings",
      "looks_like": "solid black spots densely covering the tan fur of head, neck, torso, legs and tail; black facial tear lines; yellow and white patches of the feathered mantle on the neck and chest",
      "where": "spots over all furred areas; yellow/white/black feathered pattern over the dorsal mantle"
    }
  ],
  "attached_objects": [
    "No separate object sitting on the body is clearly distinct from the body itself - the dark feathered penguin-like mantle appears fused to the dorsal side as part of the chimera. If counted as a body-shaped object, it is a penguin-like feathered torso with yellow neck patches and a small pointed tail, draped over the back from neck to rump."
  ],
  "animals": [
    "cheetah",
    "penguin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
